const content = $input.all()[0].json.content;

const campus = $input.all()[0].json.campus || 
               $('Prepare PDF for Claude').all()[0].json.campus ||
               'Unknown';

const textBlock = content.find(block => block.type === 'text');
if (!textBlock) throw new Error('No text block in Claude response');

const rawText = textBlock.text;

// Clean markdown fences if present
const cleaned = rawText.replace(/```json|```/g, '').trim();

let dishes;
try {
  dishes = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Parse failed: ' + e.message);
}

if (!Array.isArray(dishes)) {
  throw new Error('Not an array');
}

const weekOf = dishes[0]?.menu_date || new Date().toISOString().slice(0, 10);

return dishes
  .filter(dish => dish.dish_name && dish.dish_name.trim() !== '')
  .map(dish => ({
    campus,
    week_of: weekOf.substring(0, 10),
    day_name: dish.day_name || null,
    menu_date: dish.menu_date ? dish.menu_date.substring(0, 10) : null,
    category: 'Halal',
    subcategory: 'Halal',
    dish_name: dish.dish_name.trim(),
    allergens: null,
    calories: null,
    protein: null,
    fat: null,
    sodium: null,
    price: 400,
  }));

